BEGIN;

SET LOCAL search_path = public;

WITH review_input (
  professor_id, comment, ease_score, quality_score, clarity_score, fairness_score,
  attendance_required, grade_received, engagement_level, tags, created_at, import_key, course_ids
) AS (
  VALUES 
    (292::BIGINT, 'Es buena persona, pero no tan buena profesora, TODAS sus explicaciones son confusas y por eso aveces cosas muy sencillas las hace ver muy dificiles. no es tan buena la verdad'::TEXT, 6.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, '80'::TEXT, NULL::SMALLINT, ARRAY[]::TEXT[], '2026-04-20T00:00:00+00:00'::TIMESTAMPTZ, '7641d05d0e69acd01b87aedad17d85aff144f09aa41e1aeee1aba255116e10f5'::TEXT, ARRAY[1020]::BIGINT[]),
    (292::BIGINT, 'Clases largas y aburridas, nunca responde mensajes y es un verdadero estrés, por el hecho de no responder mensajes NUNCA la recomendaría, causa ansiedad. Califica muy suave y al menos es buena persona. Deja mucho que desear el curso que da.'::TEXT, 10.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, '85'::TEXT, NULL::SMALLINT, ARRAY['Asistencia obligatoria', 'Clases largas', 'Deja trabajos largos']::TEXT[], '2026-01-31T00:00:00+00:00'::TIMESTAMPTZ, '01074a3d5d3e2cce895449a002f9bc2c76fa42924d27b02bba70be6e9ee20c5a'::TEXT, ARRAY[1056]::BIGINT[]),
    (292::BIGINT, 'Busque un buen grupo desde el inicio (90% trabajos grupales), las clases son bastante largas, mueve mucho el cronograma, proyecto progresivo y grupal durante todo el semestre, es un toque complejo así que no lo dejen para el último minuto. Después de eso la profe es muy buena y humana, 10/10.'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, '80'::TEXT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Clases largas', 'Muchos proyectos grupales']::TEXT[], '2025-12-18T00:00:00+00:00'::TIMESTAMPTZ, 'b2bc8921e7b726a52e599c21dab22a2a313bd714d1c6c3c3aa98e1dc655b0904'::TEXT, ARRAY[1047]::BIGINT[]),
    (292::BIGINT, 'Es muy buena profesora, brinda apoyo y cae muy bien, sin embargo, es mucho mejor en el curso de diseño que en el de aseguramiento, ambos son sencillos, solo que en el de aseguramiento no da la impresión de estar tan pulido como el otro, igual si pueden matriculen con ella.'::TEXT, 8.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, '95'::TEXT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Brinda apoyo']::TEXT[], '2025-12-16T00:00:00+00:00'::TIMESTAMPTZ, 'c2501851fc8f123c79eb201b98d693af50440eed47a769a70860ea722be99784'::TEXT, ARRAY[1056]::BIGINT[]),
    (292::BIGINT, 'Profesor que tenía un cronograma y cada semana lo cambiaba, evaluaciones largas pero fáciles y el rubro de proyecto lo divide en un proyecto de 3 etapas durante todo el semestre, si consigue un buen grupo de trabajo y le pasa haciendo consultas (pre revisiones) se pasa fácil'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, '95'::TEXT, NULL::SMALLINT, ARRAY[]::TEXT[], '2025-12-11T00:00:00+00:00'::TIMESTAMPTZ, 'ffec0272b35ff3acff6f13107bddd094041984257041bc241f680a8fda0b7a3a'::TEXT, ARRAY[1047]::BIGINT[]),
    (292::BIGINT, 'Las clases son pesadas y es importantísimo tener un buen grupo desde el inicio. Los trabajos suelen ser largos y las instrucciones a veces un poco enredadas. Aun así, la profe es buena gente y brinda apoyo dentro de lo posible.'::TEXT, 6.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, '80'::TEXT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Deja trabajos largos', 'Muchos proyectos grupales']::TEXT[], '2025-12-04T00:00:00+00:00'::TIMESTAMPTZ, '4fa87e2b7bef5f5783b2895f758858963cc89fe295fb99d1488cba41f85ab6ec'::TEXT, ARRAY[1030]::BIGINT[]),
    (292::BIGINT, 'Esta mae es una malparida, se atrasa con todo, no sabe explicar nada, y lo deja a uno mamando, si usted no es autodidacta ni lo intente'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULL::TEXT, NULL::SMALLINT, ARRAY['Clase fácil', 'Requiere mucha lectura']::TEXT[], '2025-10-27T00:00:00+00:00'::TIMESTAMPTZ, '03ca8cb9289dd6e6a4c7299c74467fcd8d3a4b0e89718a9701e31e41fd2f28a6'::TEXT, ARRAY[1030]::BIGINT[]),
    (292::BIGINT, 'Las clases son el mayor somnífero de la historia, hace enredos que solo en su cabeza habrán sonado bien. Nada recomendable'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULL::TEXT, NULL::SMALLINT, ARRAY['Clases largas', 'Deja trabajos largos', 'Exámenes retadores']::TEXT[], '2025-10-27T00:00:00+00:00'::TIMESTAMPTZ, '265542d0305acd482208a627fb2f433d59d41b21176a0175df06c9fc5470e6c6'::TEXT, ARRAY[1030]::BIGINT[]),
    (292::BIGINT, 'Como persona es muy buena, las clases son largas y aburridas, a veces llega con un código de "ejemplo" pero lo enreda más a uno, los enunciados de los proyectos/examenes/tareas son todos mal redactados, y para terminar, nunca contesta los mensajes, y siempre se desordena y atrasa con las evaluacione'::TEXT, 6.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, '80'::TEXT, NULL::SMALLINT, ARRAY['Inspirador', 'Clases largas', 'Muchos proyectos grupales']::TEXT[], '2024-12-06T00:00:00+00:00'::TIMESTAMPTZ, '7595bde19433851af8b64808503f29fbd2fad3b553ea342e5ffcec58c548a626'::TEXT, ARRAY[1030]::BIGINT[]),
    (292::BIGINT, 'Como persona es muy buena, muy amable y respetuosa, pero es bastante desordenada, no asigna las tareas que tiene programadas, las notas las da hasta el final del semestre. Las tareas y evaluaciones en general son bastante malas, por lo cual hay que ser una persona autodidacta para aprender algo.'::TEXT, 4.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, '80'::TEXT, NULL::SMALLINT, ARRAY['Asistencia obligatoria', 'Clases largas']::TEXT[], '2024-12-03T00:00:00+00:00'::TIMESTAMPTZ, '9b42f27475269a7124288d91138461b177c736eea6cc7547802758b1a10b976c'::TEXT, ARRAY[1030]::BIGINT[]),
    (292::BIGINT, 'La profe es muy buena dando el curso de Diseño, pero en Aseguramiento, me atrevo a decir que deja mucho que desear. Mezcla mucho los temas. Al menos no es dura calificando. Y por más que le pida que entregue las notas, no las va a dar hasta el día de actas.(Pone excusas para no darlas)'::TEXT, 6.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULL::TEXT, NULL::SMALLINT, ARRAY['La participación importa', 'Asistencia obligatoria', 'Clases largas']::TEXT[], '2024-11-16T00:00:00+00:00'::TIMESTAMPTZ, '90afa5402deb536ad38c342f09a0513e46bb9b128c984085d076ac8380aba6ff'::TEXT, ARRAY[1056]::BIGINT[]),
    (292::BIGINT, 'La profesora es muy buena gente, inclusive me atrevería a decir que es muy "cosi", PERO, a como es de buena gente, es deficiente como profesora, puesto que no esperes a recibir retroalimentación de tus trabajos hasta antes de 1 hora de que vaya a entregar actas. Matricule solo presencial.'::TEXT, 6.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULL::TEXT, NULL::SMALLINT, ARRAY['Asistencia obligatoria', 'Clases largas', 'Deja trabajos largos']::TEXT[], '2024-11-08T00:00:00+00:00'::TIMESTAMPTZ, 'a2e530dcfe0dec3e63c7463fb1006a189ecc3274b21ddf6c643d539e94473648'::TEXT, ARRAY[1030]::BIGINT[]),
    (292::BIGINT, 'Como persona es muy buena gente, pero como profesora... Sus clases virtuales son SÚPER aburridas. Deja proyectos largos y con instrucciones confusas, pero al menos no califica duro. Haga sus preguntas en clase porque nunca contesta los mensajes. Si le cuesta concentrarse, no matricule con ella.'::TEXT, 6.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, '80'::TEXT, NULL::SMALLINT, ARRAY['Clase fácil', 'Deja trabajos largos', 'Muchos proyectos grupales']::TEXT[], '2024-11-08T00:00:00+00:00'::TIMESTAMPTZ, '9a6150ecbd3b0e32a201a3bf07466359980bbaec9cc560796e571674ee13429a'::TEXT, ARRAY[1030]::BIGINT[]),
    (292::BIGINT, 'No revisa los trabajos hasta finales de semestre cosa que es muy estresante. Me gustaría que usara más material visual en vez de simplemente hablar. Sus clases pueden ser un poco aburridas. Pero siempre que usted le pregunte ella va a tratar de lograr que usted entienda.'::TEXT, 4.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, '85'::TEXT, NULL::SMALLINT, ARRAY['Deja trabajos largos']::TEXT[], '2024-10-01T00:00:00+00:00'::TIMESTAMPTZ, 'eafd49388da456dab1a14e0b8b1477118dd882ef2305c596e8dea5f2f0f02a1e'::TEXT, ARRAY[1020, 1022]::BIGINT[]),
    (292::BIGINT, 'La profe es un amor, es bastante comprensiva y ayuda mucho. Tiene problemas con el cronograma y se atrasa un poco a veces pero nada muy grave. Los proyectos son largos entonces escoja un buen equipo de trabajo. Matricule con ella.'::TEXT, 4.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, '100'::TEXT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Clases largas', 'Deja trabajos largos']::TEXT[], '2024-06-17T00:00:00+00:00'::TIMESTAMPTZ, '53c8f466af7eb6325e760637a14c2587925d6ca9e407b1eba96b53712eb0ae8f'::TEXT, ARRAY[1047]::BIGINT[]),
    (292::BIGINT, 'La profe es un amor de persona, pero no entrega notas (promete entregarlo a tiempo pero no lo hace), y hace un esfuerzo en seguir el cronograma. Talvez lo complicado del curso es el proyecto que es secuencial (3 entregas), pero lo demás es easy.'::TEXT, 8.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, '80'::TEXT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Muchas tareas', 'La participación importa']::TEXT[], '2024-05-26T00:00:00+00:00'::TIMESTAMPTZ, '34c477ffff847cbc947926b1cc9fa3c6a8c8d32393b1f87a7aebe0adf49e594f'::TEXT, ARRAY[1047]::BIGINT[]),
    (292::BIGINT, 'La única razón para matricular con ella es porque no hay nadie más. Nunca es puntual, no sigue el cronograma y sus clases son aburridas. Piensa que con leer los patrones de diseño de dos páginas en específico es suficiente. Hiciera más si lo mandara a uno a ver videos, legalmente ahorre su tiempo.'::TEXT, 8.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULL::TEXT, NULL::SMALLINT, ARRAY['Muchos proyectos grupales']::TEXT[], '2024-05-06T00:00:00+00:00'::TIMESTAMPTZ, '43c71ec8331683fed5c9fff25d603262df9628b217447b5020aeacc497a3920b'::TEXT, ARRAY[1047]::BIGINT[]),
    (292::BIGINT, 'Las primeras clases son muy teóricas, pero podría cambiar pues es la primera vez que se da en Verano. Hay actividades grupales todas las clases, las cuales no son difíciles pero las indicaciones a veces no son claras. Solo 90 min de consulta por semana con cita.'::TEXT, 10.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, '95'::TEXT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Requiere mucha lectura', 'Muchos proyectos grupales']::TEXT[], '2024-01-30T00:00:00+00:00'::TIMESTAMPTZ, '7b8d899b6c5091a9bf509684345826262bbe5cc1aae016b652a4273810197265'::TEXT, ARRAY[1056]::BIGINT[]),
    (292::BIGINT, 'En las revisiones espera más de lo que pidió, no da las consultas por falta de tiempo y ve la materia corriendo. Los entregables no habilita la entrega, no ayuda si es un problema técnico. Pero no es mala profesora, ayuda dentro de lo que puede-tiene conocimiento. Un 8.5/10. :)'::TEXT, 8.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, '90'::TEXT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Aspectos de calificación claros', 'Deja trabajos largos']::TEXT[], '2023-12-04T00:00:00+00:00'::TIMESTAMPTZ, 'ab3e4e228f4b95be2c65a97a2fb53f42627132e743de4056767f0b7520116995'::TEXT, ARRAY[1047]::BIGINT[]),
    (292::BIGINT, 'La profe es un poco desordenada para dar notas, ya que la mayoría lo deja para el final. Sin embargo, la evaluación del curso favorece que, si usted entrega todos los trabajos, seguramente tenga una buena calificación. Explica bien pero el curso es un poco pesado en contenido. Matricule con ella.'::TEXT, 6.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, '75'::TEXT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Clases largas', 'Brinda apoyo']::TEXT[], '2023-11-28T00:00:00+00:00'::TIMESTAMPTZ, '2a930de2bcf6d86d00ebb3aad62d5518bc0451461bada034f8bcd78fd768766f'::TEXT, ARRAY[1047]::BIGINT[]),
    (292::BIGINT, 'La profe es muy linda persona y enseña muy bien. Definitivamente volvería a llevar cualquier curso con ella.'::TEXT, 6.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, '90'::TEXT, NULL::SMALLINT, ARRAY['Brinda apoyo', 'Tomaría su clase nuevamente']::TEXT[], '2023-11-24T00:00:00+00:00'::TIMESTAMPTZ, '8180248ecf7a6f421a917f89cf203e338e842ff0022932f8e4f2edcf8712a0fe'::TEXT, ARRAY[1030]::BIGINT[]),
    (292::BIGINT, 'La profe es un poco desordenada por el hecho de que deja la revisión de todo para el final, el proyecto puede ser tedioso pero si se va a consulta y se le pregunta bien cómo quiere las cosas les va a ir super bien. Le importa mucho el MVC, trabajar con SOLID y con los patrones de diseño que se ven.'::TEXT, 4.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, '95'::TEXT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Brinda apoyo', 'Deja trabajos largos']::TEXT[], '2023-11-02T00:00:00+00:00'::TIMESTAMPTZ, '21dbfbb6498c317f15a86a8e876b630c7619b03caf1f7e39d782ab0ab0fefba9'::TEXT, ARRAY[1047]::BIGINT[]),
    (292::BIGINT, 'Erickita es un amor, es como una mamá. En presencialidad se le entiende 20 veces más que en virtualidad. Flexible con fechas. Le cuesta mucho apegarse al cronograma inicial, sería bueno que la presionen a cumplirlo. Un toque desordenada pero pasable.'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, '95'::TEXT, NULL::SMALLINT, ARRAY[]::TEXT[], '2023-06-30T00:00:00+00:00'::TIMESTAMPTZ, '2c60082035730f276c12c0fc06c663cef2d29f570dd994c21a4f769a908cbbea'::TEXT, ARRAY[1047]::BIGINT[]),
    (292::BIGINT, 'Ayuda mucho al estudiante, es buena nota pero desordenada. Siempre le cuesta mucho cumplir con las fechas, las notas las da al final del semestre, uno sale casi en entrega de actas. Proyectos bien largos, pero se aprende mucho. Es buena en general.'::TEXT, 6.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, '55'::TEXT, NULL::SMALLINT, ARRAY['Brinda apoyo', 'Deja trabajos largos', 'Muchos proyectos grupales']::TEXT[], '2023-06-27T00:00:00+00:00'::TIMESTAMPTZ, '645a004f05950f301e32cf5b6c8c17e51d5d96d48cb40946174de04976c6b1e6'::TEXT, ARRAY[1047]::BIGINT[]),
    (292::BIGINT, 'Es la persona más desordenada que se puede encontrar en su vida como estudiante, nunca tiene listos los enunciados de los proyectos y los termina dejando una semana después de la fecha del cronograma. Termina dejando TODO para el final de semestre, los exámenes y quices están pésimamente redactados'::TEXT, 6.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULL::TEXT, NULL::SMALLINT, ARRAY['Asistencia obligatoria']::TEXT[], '2023-06-24T00:00:00+00:00'::TIMESTAMPTZ, '824350a747e8d5d78e0401ee9c5473ed76d171688155ebf912872cad31deba85'::TEXT, ARRAY[1030]::BIGINT[])
), inserted_review AS (
  INSERT INTO public.professor_review (
    professor_id, comment, ease_score, quality_score, clarity_score, fairness_score,
    attendance_required, grade_received, engagement_level, tags, status, reviewed_at, created_at, updated_at, import_key
  )
  SELECT 
    professor_id, comment, ease_score, quality_score, clarity_score, fairness_score,
    attendance_required, grade_received, engagement_level, tags, 'approved'::public.professor_review_status, now(), created_at, created_at, import_key
  FROM review_input ri
  WHERE NOT EXISTS (
    SELECT 1 FROM public.professor_review pr WHERE pr.import_key = ri.import_key
  )
  RETURNING id, import_key
), target_review AS (
  SELECT id, import_key FROM inserted_review
  UNION ALL
  SELECT pr.id, pr.import_key
  FROM public.professor_review pr
  JOIN review_input ri ON ri.import_key = pr.import_key
)
INSERT INTO public.professor_review_course (review_id, course_id)
SELECT tr.id, course_id
FROM target_review tr
JOIN review_input ri ON ri.import_key = tr.import_key
CROSS JOIN LATERAL unnest(ri.course_ids) AS course_id
ON CONFLICT DO NOTHING;

COMMIT;
